CREATE TABLE "bookmark_sets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "color" INTEGER NOT NULL, "surah" INTEGER NOT NULL, "ayah" INTEGER NOT NULL, "page" INTEGER NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "updated_at" INTEGER NOT NULL, "kind" TEXT NULL);
CREATE TABLE "reading_positions" ("id" INTEGER NOT NULL DEFAULT 1, "edition" TEXT NOT NULL, "view" TEXT NOT NULL, "surah" INTEGER NOT NULL, "ayah" INTEGER NOT NULL, "page" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "khatma" ("uuid" TEXT NOT NULL UNIQUE, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "title" TEXT NOT NULL, "edition" TEXT NOT NULL, "unit" TEXT NOT NULL DEFAULT 'page', "start_date" TEXT NOT NULL, "target_date" TEXT NOT NULL, "daily_portion" REAL NULL, "reminder_time" INTEGER NULL, "rebased_on" TEXT NULL, "completed_at" INTEGER NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "khatma_log" ("uuid" TEXT NOT NULL UNIQUE, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "khatma_uuid" TEXT NOT NULL, "date" TEXT NOT NULL, "from_page" INTEGER NOT NULL, "to_page" INTEGER NOT NULL);
CREATE TABLE "reading_session" ("uuid" TEXT NOT NULL UNIQUE, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "started_at" INTEGER NOT NULL, "ended_at" INTEGER NOT NULL, "pages" INTEGER NOT NULL, "mode" TEXT NOT NULL DEFAULT 'page', "edition" TEXT NULL);
CREATE TABLE "listening_session" ("uuid" TEXT NOT NULL UNIQUE, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "started_at" INTEGER NOT NULL, "seconds" INTEGER NOT NULL, "reciter_id" INTEGER NOT NULL);
CREATE TABLE "reflection" ("uuid" TEXT NOT NULL UNIQUE, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "surah" INTEGER NOT NULL, "ayah" INTEGER NOT NULL, "text" TEXT NOT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "outbox" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "table_name" TEXT NOT NULL, "row_id" TEXT NOT NULL, "op" TEXT NOT NULL, "payload" TEXT NOT NULL, "created_at" INTEGER NOT NULL, UNIQUE ("table_name", "row_id"));
CREATE TABLE "srs_item" ("uuid" TEXT NOT NULL UNIQUE, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "unit" TEXT NOT NULL, "from_ref" TEXT NOT NULL, "to_ref" TEXT NOT NULL, "stability" REAL NOT NULL, "difficulty" REAL NOT NULL, "due_at" INTEGER NOT NULL, "reps" INTEGER NOT NULL DEFAULT 0, "lapses" INTEGER NOT NULL DEFAULT 0, "last_review_at" INTEGER NULL);
CREATE TABLE "memorization" ("uuid" TEXT NOT NULL UNIQUE, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "unit" TEXT NOT NULL, "ref" TEXT NOT NULL, "strength" INTEGER NOT NULL);
